examples.template:
VStack(alignment: .leading, spacing: theme.spacing.space2) {
    MonarchTextField("Search", text: $query, prompt: {{placeholder}}, labelVisibility: .hidden) {
        MonarchIcon(systemName: "magnifyingglass", size: .sm).accessibilityHidden(true)
    } trailing: {
        EmptyView()
    }
    .autocorrectionDisabled()
    Text("\(matches.count) \(matches.count == 1 ? "result" : "results")\(query.isEmpty ? "" : " for \u{201C}\(query)\u{201D}")")
        .monarchTextStyle(.caption)
}
.frame(maxWidth: {{maxWidth}}, alignment: .topLeading)

examples.setupTemplate:
@Environment(\.monarchTheme) private var theme
@State private var query = ""

private let fruit = [{{fruit.0}}, {{fruit.1}}, {{fruit.2}}, {{fruit.3}}, {{fruit.4}}, {{fruit.5}}, {{fruit.6}}, {{fruit.7}}]

private var matches: [String] {
    query.isEmpty ? fruit : fruit.filter { $0.localizedCaseInsensitiveContains(query) }
}

examples.setup:
@Environment(\.monarchTheme) private var theme
@State private var query = ""

private let fruit = ["Apple", "Apricot", "Banana", "Blueberry", "Cherry", "Grape", "Mango", "Peach"]

private var matches: [String] {
    query.isEmpty ? fruit : fruit.filter { $0.localizedCaseInsensitiveContains(query) }
}

examples.code:
VStack(alignment: .leading, spacing: theme.spacing.space2) {
    MonarchTextField("Search", text: $query, prompt: "Search fruit", labelVisibility: .hidden) {
        MonarchIcon(systemName: "magnifyingglass", size: .sm).accessibilityHidden(true)
    } trailing: {
        EmptyView()
    }
    .autocorrectionDisabled()
    Text("\(matches.count) \(matches.count == 1 ? "result" : "results")\(query.isEmpty ? "" : " for \u{201C}\(query)\u{201D}")")
        .monarchTextStyle(.caption)
}
.frame(maxWidth: 300, alignment: .topLeading)

NavigationStack {
    Text(submitted.isEmpty ? "Type to search" : "Results for \(submitted)")
        .monarchTextStyle(.body)
        .searchable(text: $query, prompt: "Search invoices")
        .onSubmit(of: .search) { submitted = query }
        .task(id: query) {
            try? await Task.sleep(for: .milliseconds(300))
            if !Task.isCancelled { submitted = query }
        }
}
